#include <cstdint>
#include <vector>
#include <cstring>
#include <cmath>
#include <algorithm>

// Sparse successive shortest paths for the assignment problem.
// cost: n*k row-major doubles, nbrs: n*k row-major int32 column indices.
// out: n int32 row->col assignment. Returns 0 on success, -1 on failure.

static inline void sift_up(std::vector<double>& hd, std::vector<int>& hj,
                           std::vector<int>& hpos, int p) {
    while (p > 0) {
        int parent = (p - 1) >> 1;
        if (hd[parent] <= hd[p]) break;
        std::swap(hd[parent], hd[p]);
        std::swap(hj[parent], hj[p]);
        hpos[hj[parent]] = parent;
        hpos[hj[p]] = p;
        p = parent;
    }
}

static inline void sift_down(std::vector<double>& hd, std::vector<int>& hj,
                             std::vector<int>& hpos, int p, int hsz) {
    while (true) {
        int l = p * 2 + 1;
        if (l >= hsz) break;
        int r = l + 1;
        int s = l;
        if (r < hsz && hd[r] < hd[l]) s = r;
        if (hd[p] <= hd[s]) break;
        std::swap(hd[p], hd[s]);
        std::swap(hj[p], hj[s]);
        hpos[hj[p]] = p;
        hpos[hj[s]] = s;
        p = s;
    }
}

extern "C" int sparse_ssp(const double* cost, const int* nbrs, int n, int k, int* out) {
    const double INF = 1e100;
    const double EPS = 1e-12;

    std::vector<double> v(n, 0.0);
    std::vector<int> rowsol(n, -1), colsol(n, -1), rowslot(n, -1);

    std::vector<double> hd(n + 2);
    std::vector<int> hj(n + 2);
    std::vector<int> hpos(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred_row(n), pred_slot(n);
    std::vector<int> stamp(n, 0);
    std::vector<int> touched(n);

    for (int freerow = 0; freerow < n; ++freerow) {
        int token = freerow + 1;
        int hsz = 0;
        int ntouch = 0;
        const double* crow = cost + (size_t)freerow * k;
        const int* nrow = nbrs + (size_t)freerow * k;
        for (int t = 0; t < k; ++t) {
            int j = nrow[t];
            double d = crow[t] - v[j];
            if (stamp[j] != token || d < dist[j]) {
                dist[j] = d;
                pred_row[j] = freerow;
                pred_slot[j] = t;
                if (stamp[j] != token) {
                    stamp[j] = token;
                    touched[ntouch++] = j;
                    int p = hsz++;
                    hd[p] = d;
                    hj[p] = j;
                    hpos[j] = p;
                    sift_up(hd, hj, hpos, p);
                } else {
                    int p = hpos[j];
                    if (p >= 0) {
                        hd[p] = d;
                        sift_up(hd, hj, hpos, p);
                    }
                }
            }
        }
        int sink = -1;
        double sink_d = 0.0;
        bool found = false;
        while (hsz > 0) {
            double d = hd[0];
            int jmin = hj[0];
            --hsz;
            hpos[jmin] = -1;
            if (hsz > 0) {
                hd[0] = hd[hsz];
                hj[0] = hj[hsz];
                hpos[hj[0]] = 0;
                sift_down(hd, hj, hpos, 0, hsz);
            }
            if (d > dist[jmin] + 1e-15) continue;
            int i = colsol[jmin];
            if (i == -1) {
                sink = jmin;
                sink_d = d;
                found = true;
                break;
            }
            int slot = rowslot[i];
            const double* crowi = cost + (size_t)i * k;
            const int* nrowi = nbrs + (size_t)i * k;
            double base = crowi[slot] - v[jmin];
            for (int t = 0; t < k; ++t) {
                int j = nrowi[t];
                double alt = d + crowi[t] - v[j] - base;
                if (stamp[j] != token || alt < dist[j] - 1e-15) {
                    bool first = stamp[j] != token;
                    dist[j] = alt;
                    stamp[j] = token;
                    pred_row[j] = i;
                    pred_slot[j] = t;
                    if (first) {
                        touched[ntouch++] = j;
                        int p = hsz++;
                        hd[p] = alt;
                        hj[p] = j;
                        hpos[j] = p;
                        sift_up(hd, hj, hpos, p);
                    } else {
                        int p = hpos[j];
                        if (p >= 0) {
                            hd[p] = alt;
                            sift_up(hd, hj, hpos, p);
                        }
                    }
                }
            }
        }
        for (int p = 0; p < hsz; ++p) hpos[hj[p]] = -1;
        if (!found) {
            out[0] = -2;
            return -1;
        }
        for (int ti = 0; ti < ntouch; ++ti) {
            int j = touched[ti];
            if (dist[j] <= sink_d + EPS) v[j] += dist[j] - sink_d;
        }
        int j = sink;
        while (true) {
            int i = pred_row[j];
            int sl = pred_slot[j];
            int jprev = rowsol[i];
            rowsol[i] = j;
            rowslot[i] = sl;
            colsol[j] = i;
            if (i == freerow) break;
            j = jprev;
        }
    }
    for (int i = 0; i < n; ++i) out[i] = rowsol[i];
    return 0;
}
