// Build k nearest target candidates for each source using a grid.
// sp, tp: n*2 row-major doubles in [0,1]^2.
// nbrs_out: n*k int32.
extern "C" void build_candidates(const double* sp, const double* tp, int n, int k, int grid, int* nbrs_out) {
    int g = grid;
    int cells = g * g;
    std::vector<int> cell_of(n);
    std::vector<int> counts(cells, 0);
    for (int j = 0; j < n; ++j) {
        int cx = (int)(tp[2*j] * g);
        int cy = (int)(tp[2*j+1] * g);
        if (cx < 0) cx = 0; if (cx >= g) cx = g-1;
        if (cy < 0) cy = 0; if (cy >= g) cy = g-1;
        int c = cx * g + cy;
        cell_of[j] = c;
        counts[c]++;
    }
    std::vector<int> start(cells + 1, 0);
    for (int c = 0; c < cells; ++c) start[c+1] = start[c] + counts[c];
    std::vector<int> order(n);
    std::vector<int> cursor = start;
    for (int j = 0; j < n; ++j) {
        int c = cell_of[j];
        order[cursor[c]++] = j;
    }
    std::vector<int> buf(n);
    std::vector<double> d2(n);
    std::vector<int> sel(k);

    for (int i = 0; i < n; ++i) {
        int cx = (int)(sp[2*i] * g);
        int cy = (int)(sp[2*i+1] * g);
        if (cx < 0) cx = 0; if (cx >= g) cx = g-1;
        if (cy < 0) cy = 0; if (cy >= g) cy = g-1;
        int nbuf = 0;
        int rad = 1;
        while (nbuf < k && rad <= g) {
            int x0 = cx - rad; if (x0 < 0) x0 = 0;
            int x1 = cx + rad; if (x1 >= g) x1 = g-1;
            int y0 = cy - rad; if (y0 < 0) y0 = 0;
            int y1 = cy + rad; if (y1 >= g) y1 = g-1;
            nbuf = 0;
            for (int x = x0; x <= x1; ++x) {
                for (int y = y0; y <= y1; ++y) {
                    int c = x * g + y;
                    for (int p = start[c]; p < start[c+1]; ++p) buf[nbuf++] = order[p];
                }
            }
            ++rad;
        }
        if (nbuf < k) {
            nbuf = n;
            for (int j = 0; j < n; ++j) buf[j] = j;
        }
        double sx = sp[2*i], sy = sp[2*i+1];
        for (int t = 0; t < nbuf; ++t) {
            int j = buf[t];
            double dx = sx - tp[2*j];
            double dy = sy - tp[2*j+1];
            d2[t] = dx*dx + dy*dy;
        }
        // select k smallest indices into buf via nth + we just need any k smallest
        for (int t = 0; t < k; ++t) sel[t] = t;
        // max-heap of size k on d2 (worst at front index 0 of a sorted-desc buffer)
        auto worse = [&](int a, int b) { return d2[a] > d2[b]; };
        // build heap of sel[0:k] where worst (largest d2) is at 0? use std partial_sort
        std::nth_element(sel.begin(), sel.begin() + (k-1), sel.begin() + k,
                         [&](int a, int b){ return d2[a] < d2[b]; });
        // sel[0:k] currently just 0..k-1, nth_element within them is pointless.
        // Do selection over 0..nbuf-1
        std::vector<int> idx(nbuf);
        for (int t = 0; t < nbuf; ++t) idx[t] = t;
        std::nth_element(idx.begin(), idx.begin() + k, idx.end(),
                         [&](int a, int b){ return d2[a] < d2[b]; });
        int* row = nbrs_out + (size_t)i * k;
        for (int t = 0; t < k; ++t) row[t] = buf[idx[t]];
    }
}
