import ctypes, os, time
import numpy as np, ot
from ot.lp.emd_wrap import emd_c
lib = ctypes.CDLL(os.path.expanduser('~/otwork/liblap.dylib'))
lib.build_candidates.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_int)]
lib.sparse_ssp.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int), ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_int)]
lib.sparse_ssp.restype = ctypes.c_int

def trial(n, seed, k=48, grid=12):
    rng = np.random.default_rng(seed)
    sp = np.ascontiguousarray(rng.random((n,2)))
    tp = np.ascontiguousarray(rng.random((n,2)))
    M = np.ascontiguousarray(ot.dist(sp, tp))
    t0 = time.perf_counter()
    nbrs = np.empty((n, k), np.int32)
    lib.build_candidates(sp.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),
                         tp.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),
                         n, k, grid, nbrs.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
    cost = np.ascontiguousarray(M[np.arange(n)[:,None], nbrs])
    out = np.empty(n, np.int32)
    rc = lib.sparse_ssp(cost.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),
                        nbrs.ctypes.data_as(ctypes.POINTER(ctypes.c_int)),
                        n, k, out.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
    dt = time.perf_counter()-t0
    a = np.ascontiguousarray(np.ones(n)/n)
    G = emd_c(a,a,M,100000,1)[0]
    emd = np.argmax(G,1)
    return round(dt,5), rc==0 and bool(np.array_equal(out, emd)), rc

trial(40,0,10)
print('warmup')
for s in range(6):
    print(s, trial(600,s))
