{"command":"cat > "$HOME/otwork/lap.cpp" << 'EOF'
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>

// Solve assignment on squared Euclidean costs between two point sets,
// restricted to a spatial candidate graph. Squared Euclidean has the same
// optimum assignment as Euclidean for the unregularized problem? NO — sqrt is
// monotone per edge but the SUM of sqrts is not the same as sqrt of sum, and
// argmin of sum of distances is NOT the same as argmin of sum of squared
// distances. So we must use true Euclidean costs. Computing sqrt is fine.

static inline void sift_up(std::vector<double>& hd, std::vector<int>& hj,
                           std::vector<int>& hpos, int p) {
    while (p > 0) {
        int parent = (p - 1) >> 1;
        if (hd[parent] <= hd[p]) break;
        double td = hd[parent]; int tj = hj[parent];
        hd[parent] = hd[p]; hj[parent] = hj[p];
        hd[p] = td; hj[p] = tj;
        hpos[hj[parent]] = parent;
        hpos[hj[p]] = p;
        p = parent;
    }
}
static inline void sift_down(std::vector<double>& hd, std::vector<int>& hj,
                             std::vector<int>& hpos, int p, int hsz) {
    while (true) {
        int l = p * 2 + 1;
        if (l >= hsz) break;
        int r = l + 1;
        int s = l;
        if (r < hsz && hd[r] < hd[l]) s = r;
        if (hd[p] <= hd[s]) break;
        double td = hd[p]; int tj = hj[p];
        hd[p] = hd[s]; hj[p] = hj[s];
        hd[s] = td; hj[s] = tj;
        hpos[hj[p]] = p;
        hpos[hj[s]] = s;
        p = s;
    }
}

extern "C" int solve_points(const double* sp, const double* tp, int n, int k, int grid, int* out) {
    const double EPS = 1e-12;
    int g = grid;
    int cells = g * g;

    std::vector<int> cell_of(n), counts(cells, 0);
    for (int j = 0; j < n; ++j) {
        int cx = (int)(tp[2*j] * g); if (cx < 0) cx = 0; if (cx >= g) cx = g - 1;
        int cy = (int)(tp[2*j+1] * g); if (cy < 0) cy = 0; if (cy >= g) cy = g - 1;
        int c = cx * g + cy;
        cell_of[j] = c;
        counts[c]++;
    }
    std::vector<int> start(cells + 1, 0);
    for (int c = 0; c < cells; ++c) start[c+1] = start[c] + counts[c];
    std::vector<int> order(n), cursor = start;
    for (int j = 0; j < n; ++j) order[cursor[cell_of[j]]++] = j;

    // candidate graph stored densely n*k
    std::vector<int> nbrs((size_t)n * k);
    std::vector<double> cost((size_t)n * k);
    std::vector<int> buf(n);
    std::vector<double> d2(n);
    std::vector<int> idx(n);

    for (int i = 0; i < n; ++i) {
        int cx = (int)(sp[2*i] * g); if (cx < 0) cx = 0; if (cx >= g) cx = g - 1;
        int cy = (int)(sp[2*i+1] * g); if (cy < 0) cy = 0; if (cy >= g) cy = g - 1;
        int nbuf = 0, rad = 1;
        while (nbuf < k && rad <= g) {
            int x0 = std::max(0, cx - rad), x1 = std::min(g - 1, cx + rad);
            int y0 = std::max(0, cy - rad), y1 = std::min(g - 1, cy + rad);
            nbuf = 0;
            for (int x = x0; x <= x1; ++x)
                for (int y = y0; y <= y1; ++y) {
                    int c = x * g + y;
                    for (int p = start[c]; p < start[c+1]; ++p) buf[nbuf++] = order[p];
                }
            ++rad;
        }
        if (nbuf < k) { nbuf = n; for (int j = 0; j < n; ++j) buf[j] = j; }
        double sx = sp[2*i], sy = sp[2*i+1];
        for (int t = 0; t < nbuf; ++t) {
            int j = buf[t];
            double dx = sx - tp[2*j], dy = sy - tp[2*j+1];
            d2[t] = dx*dx + dy*dy;
            idx[t] = t;
        }
        std::nth_element(idx.begin(), idx.begin() + k, idx.begin() + nbuf,
                         [&](int a, int b){ return d2[a] < d2[b]; });
        int* nrow = nbrs.data() + (size_t)i * k;
        double* crow = cost.data() + (size_t)i * k;
        for (int t = 0; t < k; ++t) {
            int bi = idx[t];
            nrow[t] = buf[bi];
            crow[t] = std::sqrt(d2[bi]);
        }
    }

    std::vector<double> v(n, 0.0), hd(n + 2), dist(n);
    std::vector<int> rowsol(n, -1), colsol(n, -1), rowslot(n, -1);
    std::vector<int> hj(n + 2), hpos(n, -1), pred_row(n), pred_slot(n), stamp(n, 0), touched(n);

    for (int freerow = 0; freerow < n; ++freerow) {
        int token = freerow + 1;
        int hsz = 0, ntouch = 0;
        const double* crow = cost.data() + (size_t)freerow * k;
        const int* nrow = nbrs.data() + (size_t)freerow * k;
        for (int t = 0; t < k; ++t) {
            int j = nrow[t];
            double d = crow[t] - v[j];
            if (stamp[j] != token || d < dist[j]) {
                dist[j] = d;
                pred_row[j] = freerow;
                pred_slot[j] = t;
                if (stamp[j] != token) {
                    stamp[j] = token;
                    touched[ntouch++] = j;
                    int p = hsz++;
                    hd[p] = d; hj[p] = j; hpos[j] = p;
                    sift_up(hd, hj, hpos, p);
                } else if (hpos[j] >= 0) {
                    hd[hpos[j]] = d;
                    sift_up(hd, hj, hpos, hpos[j]);
                }
            }
        }
        int sink = -1; double sink_d = 0; bool found = false;
        while (hsz > 0) {
            double d = hd[0]; int jmin = hj[0];
            --hsz; hpos[jmin] = -1;
            if (hsz > 0) { hd[0] = hd[hsz]; hj[0] = hj[hsz]; hpos[hj[0]] = 0; sift_down(hd, hj, hpos, 0, hsz); }
