    for (int c=0;c<cells;++c) start[c+1]=start[c]+counts[c];
    std::vector<int> order(n), cursor=start;
    for (int j=0;j<n;++j) order[cursor[cell_of[j]]++]=j;
    std::vector<int> buf(n); std::vector<double> d2(n); std::vector<int> idx(n);
    for (int i=0;i<n;++i) {
        int cx=(int)(sp[2*i]*g); if(cx<0)cx=0; if(cx>=g)cx=g-1;
