extern "C" int dense_jv(const double* C, int n, int* out) {
    const double EPS = 1e-12;
    const double INF = 1e100;
    std::vector<double> v(n, 0.0), u(n, 0.0), dist(n), hd(n + 2);
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<int> hj(n + 2), hpos(n, -1), pred(n), stamp(n, 0), touched(n), free_rows(n);
    int nfree = 0;

    // column reduction
    for (int j = n - 1; j >= 0; --j) {
        double best = INF; int bi = 0;
        for (int i = 0; i < n; ++i) {
            double c = C[(size_t)i * n + j];
            if (c < best) { best = c; bi = i; }
        }
        v[j] = best;
        if (rowsol[bi] == -1) { rowsol[bi] = j; colsol[j] = bi; }
    }
    // reduction transfer
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j == -1) { free_rows[nfree++] = i; continue; }
        double min_alt = INF;
        const double* row = C + (size_t)i * n;
        for (int jj = 0; jj < n; ++jj) if (jj != j) {
            double red = row[jj] - v[jj];
            if (red < min_alt) min_alt = red;
        }
        v[j] = row[j] - min_alt;
        u[i] = min_alt;
    }

    for (int fi = 0; fi < nfree; ++fi) {
        int freerow = free_rows[fi];
        int token = fi + 1;
        int hsz = 0, ntouch = 0;
        const double* crow = C + (size_t)freerow * n;
        for (int j = 0; j < n; ++j) {
            double d = crow[j] - v[j];
            dist[j] = d;
            stamp[j] = token;
            pred[j] = freerow;
            touched[ntouch++] = j;
            int p = hsz++;
            hd[p] = d; hj[p] = j; hpos[j] = p;
