#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>

static inline void sift_up(std::vector<double>& hd, std::vector<int>& hj, std::vector<int>& hpos, int p) {
    while (p > 0) {
        int parent = (p - 1) >> 1;
        if (hd[parent] <= hd[p]) break;
        double td = hd[parent]; int tj = hj[parent];
        hd[parent] = hd[p]; hj[parent] = hj[p];
        hd[p] = td; hj[p] = tj;
        hpos[hj[parent]] = parent;
        hpos[hj[p]] = p;
        p = parent;
    }
}
static inline void sift_down(std::vector<double>& hd, std::vector<int>& hj, std::vector<int>& hpos, int p, int hsz) {
    while (true) {
        int l = p * 2 + 1;
        if (l >= hsz) break;
        int r = l + 1;
        int s = l;
        if (r < hsz && hd[r] < hd[l]) s = r;
        if (hd[p] <= hd[s]) break;
        double td = hd[p]; int tj = hj[p];
        hd[p] = hd[s]; hj[p] = hj[s];
        hd[s] = td; hj[s] = tj;
        hpos[hj[p]] = p;
        hpos[hj[s]] = s;
        p = s;
    }
}

// Build k nearest columns per row. nbrs/scost length n*k.
static void knn(const double* C, int n, int k, int* nbrs, double* scost) {
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        const double* row = C + (size_t)i * n;
        for (int j = 0; j < n; ++j) idx[j] = j;
        std::nth_element(idx.begin(), idx.begin() + k, idx.end(),
                         [&](int a, int b) { return row[a] < row[b]; });
        int* nb = nbrs + (size_t)i * k;
        double* sc = scost + (size_t)i * k;
        for (int t = 0; t < k; ++t) {
            nb[t] = idx[t];
            sc[t] = row[idx[t]];
        }
    }
}

struct Result {
    int nfree_after_init;
    int certified;       // 1 if reduced costs all >= -tol
    double min_rc;       // most negative reduced cost outside matching
};

// Solve sparse assignment with column-reduction init + SSP. Fills out[n] and v[n].
static int solve_sparse(const double* scost, const int* nbrs, int n, int k, int* out,
                        std::vector<double>& v, int& nfree_out) {
    const double EPS = 1e-12;
    v.assign(n, 0.0);
    std::vector<int> rowsol(n, -1), colsol(n, -1), rowslot(n, -1);

    // reverse adjacency for column reduction
    std::vector<int> counts(n, 0);
    for (int i = 0; i < n; ++i)
        for (int t = 0; t < k; ++t) counts[nbrs[(size_t)i * k + t]]++;
    std::vector<int> start(n + 1, 0);
    for (int j = 0; j < n; ++j) start[j + 1] = start[j] + counts[j];
    int total = start[n];
    std::vector<int> rev_row(total), rev_slot(total), cursor = start;
    for (int i = 0; i < n; ++i)
        for (int t = 0; t < k; ++t) {
            int j = nbrs[(size_t)i * k + t];
            int p = cursor[j]++;
            rev_row[p] = i; rev_slot[p] = t;
        }
    for (int j = n - 1; j >= 0; --j) {
        if (start[j] == start[j + 1]) { v[j] = 0.0; continue; }
        double best = 1e300; int bi = -1, bs = -1;
        for (int p = start[j]; p < start[j + 1]; ++p) {
            double c = scost[(size_t)rev_row[p] * k + rev_slot[p]];
            if (c < best) { best = c; bi = rev_row[p]; bs = rev_slot[p]; }
        }
        v[j] = best;
        if (rowsol[bi] == -1) { rowsol[bi] = j; rowslot[bi] = bs; colsol[j] = bi; }
    }
    // greedy free-to-free passes
    for (int pass = 0; pass < 4; ++pass) {
        int gained = 0;
        for (int i = 0; i < n; ++i) if (rowsol[i] == -1) {
            const double* sc = scost + (size_t)i * k;
            const int* nb = nbrs + (size_t)i * k;
            double best = 1e300; int bj = -1, bs = -1;
            for (int t = 0; t < k; ++t) {
                int j = nb[t];
                if (colsol[j] != -1) continue;
                double r = sc[t] - v[j];
                if (r < best) { best = r; bj = j; bs = t; }
            }
            if (bj != -1) { rowsol[i] = bj; rowslot[i] = bs; colsol[bj] = i; ++gained; }
        }
        if (!gained) break;
    }

    std::vector<int> free_rows(n);
    int nfree = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] == -1) free_rows[nfree++] = i;
    nfree_out = nfree;

    std::vector<double> hd(n + 2), dist(n);
    std::vector<int> hj(n + 2), hpos(n, -1), pred_row(n), pred_slot(n), stamp(n, 0), touched(n);

    for (int fi = 0; fi < nfree; ++fi) {
        int freerow = free_rows[fi];
        int token = fi + 1;
        int hsz = 0, ntouch = 0;
        const double* sc = scost + (size_t)freerow * k;
        const int* nb = nbrs + (size_t)freerow * k;
        for (int t = 0; t < k; ++t) {
            int j = nb[t];
            double d = sc[t] - v[j];
            dist[j] = d; stamp[j] = token; pred_row[j] = freerow; pred_slot[j] = t;
            touched[ntouch++] = j;
            int p = hsz++;
            hd[p] = d; hj[p] = j; hpos[j] = p;
            sift_up(hd, hj, hpos, p);
        }
        int sink = -1; double sink_d = 0; bool found = false;
        while (hsz > 0) {
            double d = hd[0]; int jmin = hj[0];
            --hsz; hpos[jmin] = -1;
            if (hsz > 0) { hd[0] = hd[hsz]; hj[0] = hj[hsz]; hpos[hj[0]] = 0; sift_down(hd, hj, hpos, 0, hsz); }
            if (stamp[jmin] != token || d > dist[jmin] + 1e-15) continue;
            int i = colsol[jmin];
            if (i == -1) { sink = jmin; sink_d = d; found = true; break; }
            int slot = rowslot[i];
            const double* sci = scost + (size_t)i * k;
            const int* nbi = nbrs + (size_t)i * k;
            double base = sci[slot] - v[jmin];
            for (int t = 0; t < k; ++t) {
                int j = nbi[t];
                double alt = d + sci[t] - v[j] - base;
                if (stamp[j] != token || alt < dist[j] - 1e-15) {
                    bool first = stamp[j] != token;
                    dist[j] = alt; stamp[j] = token; pred_row[j] = i; pred_slot[j] = t;
                    if (first) {
                        touched[ntouch++] = j;
                        int p = hsz++;
                        hd[p] = alt; hj[p] = j; hpos[j] = p;
                        sift_up(hd, hj, hpos, p);
                    } else if (hpos[j] >= 0) {
                        hd[hpos[j]] = alt; sift_up(hd, hj, hpos, hpos[j]);
                    }
                }
            }
        }
        for (int p = 0; p < hsz; ++p) hpos[hj[p]] = -1;
        if (!found) { out[0] = -2; return -1; }
        for (int ti = 0; ti < ntouch; ++ti) {
            int j = touched[ti];
            if (stamp[j] == token && dist[j] <= sink_d + EPS) v[j] += dist[j] - sink_d;
        }
        int j = sink;
        while (true) {
            int i = pred_row[j]; int sl = pred_slot[j]; int jp = rowsol[i];
            rowsol[i] = j; rowslot[i] = sl; colsol[j] = i;
            if (i == freerow) break;
            j = jp;
        }
    }
    for (int i = 0; i < n; ++i) out[i] = rowsol[i];
    return 0;
}

extern "C" int solve_assign(const double* C, int n, int k, int* out, double* stats) {
    // stats[0]=knn_ms, [1]=solve_ms, [2]=cert_ms, [3]=nfree, [4]=min_rc, [5]=certified
    std::vector<int> nbrs((size_t)n * k);
    std::vector<double> scost((size_t)n * k);
    knn(C, n, k, nbrs.data(), scost.data());
    std::vector<double> v;
    int nfree = 0;
    int rc = solve_sparse(scost.data(), nbrs.data(), n, k, out, v, nfree);
    if (rc != 0) { stats[5] = 0; return rc; }
    // certify
    double min_rc = 0.0;
    const double tol = 1e-8;
    for (int i = 0; i < n; ++i) {
        int m = out[i];
        double u = C[(size_t)i * n + m] - v[m];
        const double* row = C + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            double r = row[j] - u - v[j];
            if (r < min_rc) min_rc = r;
        }
    }
    stats[3] = nfree;
    stats[4] = min_rc;
    stats[5] = (min_rc >= -tol) ? 1.0 : 0.0;
    return 0;
}
