// Dense Jonker-Volgenant assignment (minimization), adapted from the
// public-domain implementation by Jonker & Volgenant (1987) / scipy's
// rectangular_lsap structure, written for square float costs.
#include <cstdint>
#include <vector>
#include <cmath>
#include <limits>
#include <algorithm>

extern "C" int jv_solve(const double* cost, int n, int* rowsol) {
    const double INF = 1e100;
    std::vector<double> u(n), v(n), d(n);
    std::vector<int> colsol(n, -1), pred(n), free_rows(n);
    std::vector<char> free_col(n, 1);

    // COLUMN REDUCTION
