// Square Jonker-Volgenant LAP (minimization), floating-point adaptation of
// the 1987 algorithm. Dense cost, row-major.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>

extern "C" int jv_solve(const double* cost, int n, int* rowsol) {
    const double BIG = 1e100;
    std::vector<double> v(n, 0.0), d(n);
    std::vector<int> colsol(n, -1), pred(n);
    std::vector<char> scanned(n);

    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    // ---- column reduction ----
    for (int j = n - 1; j >= 0; --j) {
        double m = cost[j];
        int im = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < m) { m = c; im = i; }
        }
        v[j] = m;
        if (rowsol[im] < 0) { rowsol[im] = j; colsol[j] = im; }
    }

    // ---- reduction transfer + free list ----
    std::vector<int> free_rows(n);
    int nfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] < 0) {
            free_rows[nfree++] = i;
        } else {
            int j1 = rowsol[i];
            double m = BIG;
            const double* row = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) if (j != j1) {
                double h = row[j] - v[j];
                if (h < m) m = h;
            }
            v[j1] -= m;
        }
    }

    // ---- augmenting row reduction ----
    int guard = 0;
    while (nfree > 0 && guard < n) {
        ++guard;
        int nfree_before = nfree;
        int k = 0;
        int new_free = 0;
        std::vector<int> next_free(nfree);
        while (k < nfree) {
            int i = free_rows[k];
            ++k;
            const double* row = cost + (size_t)i * n;
            double umin = BIG, usub = BIG;
            int j1 = 0, j2 = -1;
            for (int j = 0; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; j2 = j; }
                    else { usub = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            double delta = usub - umin;
            if (delta > 0) v[j1] -= delta;
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = colsol[j2]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (delta > 0) next_free[new_free++] = i0;   // unique, retry immediately-ish
                else next_free[new_free++] = i0;
            }
        }
        nfree = new_free;
        for (int t = 0; t < nfree; ++t) free_rows[t] = next_free[t];
        if (nfree >= nfree_before) break;  // no progress: fall through to augmentation
    }

    // rebuild free list from actual assignment (row reduction may be partial)
    nfree = 0;
    std::fill(colsol.begin(), colsol.end(), -1);
    for (int i = 0; i < n; ++i) {
        int j = rowsol[i];
        if (j >= 0 && colsol[j] < 0) colsol[j] = i;
        else rowsol[i] = -1;
    }
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) free_rows[nfree++] = i;

    // ---- augmentation (Dijkstra with Dial-like linear scan, JV style) ----
    std::vector<int> ready(n);
    for (int f = 0; f < nfree; ++f) {
        int freerow = free_rows[f];
        for (int j = 0; j < n; ++j) {
            d[j] = cost[(size_t)freerow * n + j] - v[j];
            pred[j] = freerow;
            scanned[j] = 0;
        }
        int unassigned = -1;
        int nready = 0;
        double mind = 0;
        // initialize ready with all columns; scan in distance order via repeated min
        // (n is 600, free rows ~250, this is the O(n^2 * nfree) part — acceptable if tight)
        while (true) {
            mind = BIG;
            int jmin = -1;
            for (int j = 0; j < n; ++j) if (!scanned[j] && d[j] < mind) { mind = d[j]; jmin = j; }
            scanned[jmin] = 1;
            int i = colsol[jmin];
            if (i < 0) { unassigned = jmin; break; }
            const double* row = cost + (size_t)i * n;
            double base = row[jmin] - v[jmin];
            for (int j = 0; j < n; ++j) if (!scanned[j]) {
                double alt = mind + row[j] - v[j] - base;
                if (alt < d[j]) { d[j] = alt; pred[j] = i; }
            }
        }
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += d[j] - mind;
        int j = unassigned;
        while (true) {
            int i = pred[j];
            int jprev = rowsol[i];
            rowsol[i] = j;
            colsol[j] = i;
            if (i == freerow) break;
            j = jprev;
        }
        (void)nready; (void)ready;
    }
    return 0;
}
