#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>

// Dense Bertsekas auction (minimization) with epsilon scaling.
// cost: row-major n*n. Returns row->col in out. 0 on success.
extern "C" int auction_solve(const double* cost, int n, int* out) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assign(n, -1);
    std::vector<int> queue(n);

    // cost range ~ [0, 1.5]; start eps at a fraction of the mean cost
    double eps = 0.05;
    const double eps_target = 1e-10;
    const double factor = 0.25;

    for (int phase = 0; phase < 64 && eps >= eps_target * 0.5; ++phase) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        for (int i = 0; i < n; ++i) queue[i] = i;
        int qh = 0, qt = n, qcount = n;
        // ring buffer of size n is enough if we compact; use a larger ring
        // We'll just rescan when the queue wraps by using modulo on a vector of size n
        // and a "in_queue" flag to avoid duplicates? Persons are unassigned iff not in assign,
        // and we only enqueue when displaced, so each person is in the queue at most once. A ring of size n suffices
        // IF we never enqueue more than n before dequeuing n. Worst case a displacement cascade enqueues while
        // the queue still holds everyone: need size 2n. Use modulo 2n.
        break;
    }

    const int Q = n * 2 + 8;
    std::vector<int> ring(Q);
    for (int phase = 0; phase < 64; ++phase) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        for (int i = 0; i < n; ++i) ring[i] = i;
        int qh = 0, qt = n, qcount = n;
        long guard = 0;
        const long limit = (long)n * 400;
        bool ok = true;
        while (qcount > 0) {
            int i = ring[qh];
            qh = (qh + 1) % Q;
            --qcount;
            const double* row = cost + (size_t)i * n;
            double best = -1e300, second = -1e300;
            int best_j = 0;
            for (int j = 0; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; best_j = j; }
                else if (val > second) second = val;
            }
            price[best_j] += (best - second) + eps;
            int prev = owner[best_j];
            if (prev >= 0) {
                assign[prev] = -1;
                ring[qt] = prev;
                qt = (qt + 1) % Q;
                ++qcount;
            }
            owner[best_j] = i;
            assign[i] = best_j;
            if (++guard > limit) { ok = false; break; }
        }
        if (!ok) { out[0] = -2; return -1; }
        if (eps <= eps_target) break;
        eps *= factor;
        if (eps < eps_target) eps = eps_target;
    }
    for (int i = 0; i < n; ++i) out[i] = assign[i];
    return 0;
}
