extern "C" int auction_points(const double* sp, const double* tp, int n, int k, int grid, int* out) {
    int g = grid, cells = g * g;
    std::vector<int> cell_of(n), counts(cells, 0);
    for (int j = 0; j < n; ++j) {
        int cx = (int)(tp[2 * j] * g); if (cx < 0) cx = 0; if (cx >= g) cx = g - 1;
        int cy = (int)(tp[2 * j + 1] * g); if (cy < 0) cy = 0; if (cy >= g) cy = g - 1;
        cell_of[j] = cx * g + cy;
        counts[cell_of[j]]++;
    }
    std::vector<int> start(cells + 1, 0);
    for (int c = 0; c < cells; ++c) start[c + 1] = start[c] + counts[c];
    std::vector<int> order(n), cursor = start;
    for (int j = 0; j < n; ++j) order[cursor[cell_of[j]]++] = j;

    std::vector<int> nbrs((size_t)n * k);
    std::vector<double> cost((size_t)n * k);
    std::vector<int> buf(n), idx(n);
    std::vector<double> d2(n);
    for (int i = 0; i < n; ++i) {
        int cx = (int)(sp[2 * i] * g); if (cx < 0) cx = 0; if (cx >= g) cx = g - 1;
        int cy = (int)(sp[2 * i + 1] * g); if (cy < 0) cy = 0; if (cy >= g) cy = g - 1;
        int nbuf = 0, rad = 1;
        while (nbuf < k && rad <= g) {
            int x0 = std::max(0, cx - rad), x1 = std::min(g - 1, cx + rad);
            int y0 = std::max(0, cy - rad), y1 = std::min(g - 1, cy + rad);
            nbuf = 0;
            for (int x = x0; x <= x1; ++x)
                for (int y = y0; y <= y1; ++y) {
                    int c = x * g + y;
                    for (int p = start[c]; p < start[c + 1]; ++p) buf[nbuf++] = order[p];
                }
            ++rad;
        }
        if (nbuf < k) { nbuf = n; for (int j = 0; j < n; ++j) buf[j] = j; }
        double sx = sp[2 * i], sy = sp[2 * i + 1];
        for (int t = 0; t < nbuf; ++t) {
            int j = buf[t];
            double dx = sx - tp[2 * j], dy = sy - tp[2 * j + 1];
            d2[t] = dx * dx + dy * dy;
            idx[t] = t;
        }
        std::nth_element(idx.begin(), idx.begin() + k, idx.begin() + nbuf,
                         [&](int a, int b) { return d2[a] < d2[b]; });
        for (int t = 0; t < k; ++t) {
            nbrs[(size_t)i * k + t] = buf[idx[t]];
            cost[(size_t)i * k + t] = std::sqrt(d2[idx[t]]);
        }
    }

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assign(n, -1);
    const int Q = n * 2 + 8;
    std::vector<int> ring(Q);
    double eps = 0.05, eps_target = 1e-10, factor = 0.25;
    for (int phase = 0; phase < 64; ++phase) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        for (int i = 0; i < n; ++i) ring[i] = i;
        int qh = 0, qt = n, qcount = n;
        long guard = 0;
        const long limit = (long)n * 500;
        bool ok = true;
        while (qcount > 0) {
            int i = ring[qh];
            qh = (qh + 1) % Q;
            --qcount;
            double best = -1e300, second = -1e300;
            int best_j = -1;
            const double* sc = cost.data() + (size_t)i * k;
            const int* nb = nbrs.data() + (size_t)i * k;
            for (int t = 0; t < k; ++t) {
                int j = nb[t];
                double val = -sc[t] - price[j];
                if (val > best) { second = best; best = val; best_j = j; }
                else if (val > second) second = val;
            }
            if (best_j < 0) { ok = false; break; }
            if (second < -1e299) second = best - 1.0;
            price[best_j] += (best - second) + eps;
            int prev = owner[best_j];
            if (prev >= 0) {
                assign[prev] = -1;
                ring[qt] = prev;
                qt = (qt + 1) % Q;
                ++qcount;
            }
            owner[best_j] = i;
            assign[i] = best_j;
            if (++guard > limit) { ok = false; break; }
        }
        if (!ok) { out[0] = -2; return -1; }
        if (eps <= eps_target) break;
        eps *= factor;
        if (eps < eps_target) eps = eps_target;
    }
    for (int i = 0; i < n; ++i) out[i] = assign[i];
    return 0;
}
