// Parallel dense auction. Each phase, unassigned persons are split across threads;
// bids are computed independently, then applied serially (bid conflicts resolved by
// keeping the highest bid per object — the Gauss-Seidel auction variant is sequential,
// so we use the Jacobi/synchronous auction which is also correct).

struct Bid { int i; int j; double price; };

extern "C" int auction_par(const double* cost, int n, int* out, int nthreads) {
    if (nthreads < 1) nthreads = 1;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assign(n, -1);

    double eps = 0.05, eps_target = 1e-10, factor = 0.25;
    std::vector<std::vector<Bid>> bids(nthreads);

    for (int phase = 0; phase < 64; ++phase) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        std::vector<int> unassigned(n);
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int guard = 0;
        while (!unassigned.empty()) {
            int nu = (int)unassigned.size();
            for (auto& b : bids) b.clear();
            auto worker = [&](int tid, int lo, int hi) {
                for (int p = lo; p < hi; ++p) {
                    int i = unassigned[p];
                    const double* row = cost + (size_t)i * n;
                    double best = -1e300, second = -1e300;
                    int best_j = 0;
                    for (int j = 0; j < n; ++j) {
                        double val = -row[j] - price[j];
                        if (val > best) { second = best; best = val; best_j = j; }
                        else if (val > second) second = val;
