                    bids[tid].push_back({i, best_j, price[best_j] + (best - second) + eps});
                }
            };
            std::vector<std::thread> threads;
            int chunk = (nu + nthreads - 1) / nthreads;
            for (int t = 0; t < nthreads; ++t) {
                int lo = t * chunk, hi = std::min(nu, lo + chunk);
                if (lo < hi) threads.emplace_back(worker, t, lo, hi);
            }
            for (auto& th : threads) th.join();
            // apply bids: for each object keep the highest bid
            std::vector<int> best_bidder(n, -1);
            std::vector<double> best_price(n, -1e300);
            for (int t = 0; t < nthreads; ++t) {
                for (auto& b : bids[t]) {
                    if (b.price > best_price[b.j]) { best_price[b.j] = b.price; best_bidder[b.j] = b.i; }
                }
            }
            std::vector<char> got(n, 0);
            unassigned.clear();
            for (int j = 0; j < n; ++j) {
                int i = best_bidder[j];
                if (i < 0) continue;
                price[j] = best_price[j];
                int prev = owner[j];
                if (prev >= 0 && prev != i) { assign[prev] = -1; }
                owner[j] = i;
                assign[i] = j;
                got[i] = 1;
            }
            for (int i = 0; i < n; ++i) if (assign[i] < 0) unassigned.push_back(i);
            if (++guard > n * 20) { out[0] = -2; return -1; }
        }
        if (eps <= eps_target) break;
        eps *= factor;
        if (eps < eps_target) eps = eps_target;
    }
    for (int i = 0; i < n; ++i) out[i] = assign[i];
    return 0;
}
