#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>

extern "C" int auction2(const double* cost, int n, int* out) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assign(n, -1);
    const int Q = n * 2 + 8;
    std::vector<int> ring(Q);

    double eps = 0.1;
    const double eps_target = 1e-10;
    const double factor = 0.2;

    for (int phase = 0; phase < 48; ++phase) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        for (int i = 0; i < n; ++i) ring[i] = i;
        int qh = 0, qt = n, qcount = n;
        long guard = 0;
        const long limit = (long)n * 300;
        while (qcount > 0) {
            int i = ring[qh];
            if (++qh == Q) qh = 0;
            --qcount;
            const double* row = cost + (size_t)i * n;
            double best = -1e300, second = -1e300;
            int best_j = 0;
            // manual unroll by 4
            int j = 0;
            for (; j + 3 < n; j += 4) {
                double p0 = price[j], p1 = price[j+1], p2 = price[j+2], p3 = price[j+3];
                double v0 = -row[j] - p0, v1 = -row[j+1] - p1, v2 = -row[j+2] - p2, v3 = -row[j+3] - p3;
                if (v0 > best) { second = best; best = v0; best_j = j; }
                else if (v0 > second) second = v0;
                if (v1 > best) { second = best; best = v1; best_j = j+1; }
                else if (v1 > second) second = v1;
                if (v2 > best) { second = best; best = v2; best_j = j+2; }
                else if (v2 > second) second = v2;
                if (v3 > best) { second = best; best = v3; best_j = j+3; }
                else if (v3 > second) second = v3;
            }
            for (; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; best_j = j; }
                else if (val > second) second = val;
            }
            price[best_j] += (best - second) + eps;
            int prev = owner[best_j];
            if (prev >= 0) {
                assign[prev] = -1;
                ring[qt] = prev;
                if (++qt == Q) qt = 0;
                ++qcount;
            }
            owner[best_j] = i;
            assign[i] = best_j;
            if (++guard > limit) { out[0] = -2; return -1; }
        }
        if (eps <= eps_target) break;
        eps *= factor;
        if (eps < eps_target) eps = eps_target;
    }
    for (int i = 0; i < n; ++i) out[i] = assign[i];
    return 0;
}
