extern "C" double bench(const double* C, int n, int k, int reps) {
    std::vector<int> idx(n);
    auto t0 = std::chrono::steady_clock::now();
    for (int r = 0; r < reps; ++r) {
        for (int i = 0; i < n; ++i) {
