#include <cstdint>
#include <vector>
#include <chrono>
#include <cstdio>

// Simulate the dominant Hungarian/JV scan: for each of `passes` rows,
// scan all columns once (plus a second pass), touching two double arrays.
extern "C" double bench_scan(const double* C, int n, int passes) {
    std::vector<double> v(n, 0.1), d(n);
    std::vector<char> scanned(n, 0);
    volatile double sink = 0;
    auto t0 = std::chrono::steady_clock::now();
    for (int p = 0; p < passes; ++p) {
        int i = p % n;
        const double* row = C + (size_t)i * n;
        double best = 1e300;
        int bj = 0;
        for (int j = 0; j < n; ++j) {
            double h = row[j] - v[j];
            d[j] = h;
            if (h < best) { best = h; bj = j; }
        }
        // second scan: relax
        double base = best;
        for (int j = 0; j < n; ++j) {
            double alt = row[j] - v[j] + base;
            if (alt < d[j]) d[j] = alt;
        }
        sink += d[bj];
    }
    auto t1 = std::chrono::steady_clock::now();
    (void)sink;
    return std::chrono::duration<double>(t1 - t0).count();
}
