#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <cstdio>

// Faithful JV phases, counting free rows after each phase.
extern "C" void jv_profile(const double* cost, int n, double* stats) {
    const double BIG = 1e100;
    std::vector<double> v(n, 0.0);
    std::vector<int> rowsol(n, -1), colsol(n, -1), free_rows(n);

    auto t0 = std::chrono::steady_clock::now();
    // column reduction
    for (int j = n - 1; j >= 0; --j) {
        double m = cost[j]; int im = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < m) { m = c; im = i; }
        }
        v[j] = m;
        if (rowsol[im] < 0) { rowsol[im] = j; colsol[j] = im; }
    }
    int nfree = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) free_rows[nfree++] = i;
    else {
        int j1 = rowsol[i];
        double m = BIG;
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) if (j != j1) {
            double h = row[j] - v[j];
            if (h < m) m = h;
        }
        v[j1] -= m;
    }
    auto t1 = std::chrono::steady_clock::now();
    stats[0] = nfree;

    // augmenting row reduction: repeat until no decrease
    int rounds = 0;
    while (nfree > 0 && rounds < 4) {
        ++rounds;
        int nfree_before = nfree;
        std::vector<int> next;
        next.reserve(nfree);
        for (int k = 0; k < nfree; ++k) {
            int i = free_rows[k];
            const double* row = cost + (size_t)i * n;
            double u1 = BIG, u2 = BIG; int j1 = 0, j2 = -1;
            for (int j = 0; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < u2) {
                    if (h >= u1) { u2 = h; j2 = j; }
                    else { u2 = u1; u1 = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (u1 < u2) v[j1] -= (u2 - u1);
            else if (i0 >= 0 && j2 >= 0) { j1 = j2; i0 = colsol[j2]; }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) next.push_back(i0);
        }
        nfree = (int)next.size();
        for (int k = 0; k < nfree; ++k) free_rows[k] = next[k];
        if (nfree >= nfree_before) break;
    }
    auto t2 = std::chrono::steady_clock::now();
    stats[1] = nfree;
    stats[2] = rounds;
    stats[3] = std::chrono::duration<double, std::milli>(t1 - t0).count();
    stats[4] = std::chrono::duration<double, std::milli>(t2 - t1).count();
}
